import json
import boto3
import os
import urllib.request
from flask import Flask, request, jsonify, session

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

STEP_FUNCTION_ARN = os.environ.get('STEP_FUNCTION_ARN')

def get_aws_credentials():
    """Fetch temporary credentials from instance metadata service"""
    try:
        token_url = 'http://169.254.169.254/latest/api/token'
        token_req = urllib.request.Request(token_url, method='PUT')
        token_req.add_header('X-aws-ec2-metadata-token-ttl-seconds', '21600')
        token = urllib.request.urlopen(token_req, timeout=2).read().decode()

        role_url = 'http://169.254.169.254/latest/meta-data/iam/security-credentials/'
        role_req = urllib.request.Request(role_url)
        role_req.add_header('X-aws-ec2-metadata-token', token)
        role_name = urllib.request.urlopen(role_req, timeout=2).read().decode()

        creds_url = f'http://169.254.169.254/latest/meta-data/iam/security-credentials/{role_name}'
        creds_req = urllib.request.Request(creds_url)
        creds_req.add_header('X-aws-ec2-metadata-token', token)
        creds_data = json.loads(urllib.request.urlopen(creds_req, timeout=2).read().decode())
        return creds_data
    except Exception as e:
        return None

def start_workflow(action, target_user, parameters):
    """Start a Step Functions workflow execution"""
    creds = get_aws_credentials()
    if creds:
        client = boto3.client(
            'stepfunctions',
            aws_access_key_id=creds['AccessKeyId'],
            aws_secret_access_key=creds['SecretAccessKey'],
            aws_session_token=creds['Token'],
            region_name=os.environ.get('AWS_REGION', 'us-east-1')
        )
    else:
        client = boto3.client('stepfunctions')

    workflow_input = {
        'action': action,
        'target_user': target_user,
        'parameters': parameters,
        'initiated_by': session.get('user_id', 'anonymous')
    }

    response = client.start_execution(
        stateMachineArn=STEP_FUNCTION_ARN,
        input=json.dumps(workflow_input)
    )
    return response['executionArn']

@app.route('/api/workflow/execute', methods=['POST'])
def execute_workflow():
    """Execute a workflow action - NOTE: no CSRF token validation"""
    # Authentication check
    if 'user_id' not in session:
        return jsonify({'error': 'Unauthorized'}), 401

    data = request.get_json(force=True, silent=True)
    if not data:
        # Also accept form data for backward compatibility
        data = {
            'action': request.form.get('action'),
            'target_user': request.form.get('target_user'),
            'parameters': json.loads(request.form.get('parameters', '{}')),
        }

    action = data.get('action')
    target_user = data.get('target_user')
    parameters = data.get('parameters', {})

    if not action or not target_user:
        return jsonify({'error': 'Missing required fields'}), 400

    # Validate action is in allowed list
    allowed_actions = ['promote', 'demote', 'suspend', 'transfer', 'delete_account']
    if action not in allowed_actions:
        return jsonify({'error': 'Invalid action'}), 400

    try:
        execution_arn = start_workflow(action, target_user, parameters)
        return jsonify({'status': 'started', 'execution_arn': execution_arn})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/workflow/status/<execution_id>')
def workflow_status(execution_id):
    """Check workflow execution status"""
    if 'user_id' not in session:
        return jsonify({'error': 'Unauthorized'}), 401

    client = boto3.client('stepfunctions')
    try:
        response = client.describe_execution(executionArn=execution_id)
        return jsonify({
            'status': response['status'],
            'started': str(response['startDate']),
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
